import { useMemo } from 'react'
import WindowFrame from './WindowFrame'
import ErrorBoundary from '../ErrorBoundary'
import ListingWindow from './ListingWindow'
import SettlementWindow from './SettlementWindow'
import BookWindow from './BookWindow'
import TradesWindow from './TradesWindow'
import HoldersWindow from './HoldersWindow'
import TimelineWindow from './TimelineWindow'
import { useServerNow } from '../../hooks/useServerClock'
import { slotStatus } from '../../utils/slotStatus'
import { windowMeta } from '../../utils/slotWindowMeta'

/**
 * One of the six slot windows, in its frame.
 *
 * The frame — title, glyph, count, state badge, summary, tone and the controls — comes
 * from `windowMeta`, the same function the window bar's chips read, so a chip and the
 * title bar it opens can never disagree about a count or a lock. The window inside
 * draws everything else, from the one `slot` payload the whole page shares.
 *
 * **The window draws its own head, body and foot, inside the frame's body**, rather
 * than handing them to WindowFrame's `head` and `foot`. Two things follow from that,
 * and both are the point:
 *
 * - The ErrorBoundary sits inside the frame. A window that throws while drawing keeps
 *   its title bar and its ×, and says "Order book window stopped" under them, instead
 *   of leaving a hole in the canvas with no way to close it.
 * - Everything derived from the slot is under the memoised window. This component is
 *   redrawn whenever the page is (the canvas hands it fresh controls every render,
 *   which is cheap: a title bar), but the window below it only redraws when `slot` or
 *   `ctx` does. So typing in a Participate field never re-renders a 200-row tape.
 *
 * The parts are laid out by `layout`, one of the two functions at the bottom of this
 * file: pinned head and foot around a scrolling body on the canvas, all three stacked
 * at natural height when embedded (flow mode). A window calls it with what it has —
 * `{ head, body, foot, scroll, empty }` — and never needs to know which mode it is in.
 *
 * Inline windows must not own a shell or `[data-board]`, query the document, or add
 * document-level listeners beyond their own effects: they share this document with
 * the page and with each other.
 */
export default function SlotWindow({
  windowKey, slot, ctx, controls, focusToken = null, embedded = false,
}) {
  const status = useMemo(() => slotStatus(slot), [slot])
  // Settlement's summary counts down ("Settles in 31h 12m"), so its title bar follows
  // the server clock; no other window's bar says anything that moves with time. A null
  // clock is how the others opt out — the hook then never sets a timer.
  const nowMs = useServerNow(windowKey === 'settlement' ? ctx?.clock : null, 30_000)
  const isCreator = ctx?.isCreator
  const meta = useMemo(
    () => windowMeta(windowKey, slot, { status, isCreator, nowMs: nowMs ?? undefined }),
    [windowKey, slot, status, isCreator, nowMs])

  const layout = embedded ? embeddedLayout : canvasLayout
  const win = slot ? windowFor(windowKey, { slot, ctx: ctx || NO_CTX, layout }) : null
  if (!win) return null

  return (
    <WindowFrame
      id={windowKey}
      title={meta.title}
      glyph={meta.glyph}
      count={meta.count}
      badge={meta.badge}
      summary={meta.summary}
      tone={meta.tone}
      stale={!!ctx?.stale}
      onClose={controls?.onClose}
      addMenu={controls?.addMenu}
      openTo={controls?.openTo}
      focusToken={focusToken}
      embedded={embedded}
      // The window lays out its own parts (see above), so the frame's body is only a
      // column for them: no padding and no scrolling of its own.
      bodyClassName={embedded ? 'p-0' : 'p-0 overflow-hidden flex flex-col'}>
      {/* Keyed by window, so a boundary that caught one window's crash does not go on
          showing it after a layout change puts a different window in this pane. */}
      <ErrorBoundary key={windowKey} compact label={`${meta.title} window`}>
        {win}
      </ErrorBoundary>
    </WindowFrame>
  )
}

const NO_CTX = {}

// A switch rather than an exported registry: the six windows are the slot page's own,
// and nothing else should be able to add one or swap one out.
function windowFor(key, props) {
  switch (key) {
    case 'listing':    return <ListingWindow {...props} />
    case 'settlement': return <SettlementWindow {...props} />
    case 'book':       return <BookWindow {...props} />
    case 'trades':     return <TradesWindow {...props} />
    case 'holders':    return <HoldersWindow {...props} />
    case 'timeline':   return <TimelineWindow {...props} />
    default:           return null
  }
}

// ── Layouts ─────────────────────────────────────────────────────────────────────
//
// Plain functions, not components, and defined once out here: they are passed to the
// memoised windows as a prop, and a new function every render would defeat the memo.
// The classes are WindowFrame's own head, body and foot (spec 6.2).
//
// - `head` is pinned under the title bar: the figures a window must answer with
//   before anyone scrolls, because a rail window can be 116px of body on a laptop.
// - `scroll` names the body and makes it a focusable scroller (Book and Trades), so a
//   keyboard can scroll a ladder or a tape that has no other focusable content.
// - `empty` is `{ title, reason }`, drawn centred in the body in place of `body`.
//
// `data-scroller` marks the one element that scrolls, for the Book's centring.

const SCROLL_FOCUS = 'focus:outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-violet-400/70'

function canvasLayout({ head, body, foot, scroll, empty }) {
  return (
    <>
      {head && <div className="shrink-0 border-b border-white/5">{head}</div>}
      {/* The padding is on the inner box, not the scroller, so the scroller can shrink
          all the way to nothing. A scroller's own padding is a floor it cannot go
