import { Fragment, memo, useMemo } from 'react'
import Glyph from './Glyph'
import { StatStrip } from './WindowFrame'
import { tapeSummary } from '../../utils/marketMath'
import { slotStatus } from '../../utils/slotStatus'
import { dayTime, rate, secs } from '../../utils/format'

/**
 * The tape: every executed trade the server sends, newest first.
 *
 * `all_trades`, the newest 200, in place of the old three-row preview of
 * `recent_trades` — it is the same list the chart plots, so a dot on the chart and a
 * row here can never disagree. The figures pinned above it are Commerce's, from the
 * same helper, for the same reason.
 *
 * A run of blind-auction fills sits under a divider of its own: an uncrossing is a
 * labelled event (§1.2), not more ticks, and read as ordinary rows it looks like a
 * sudden burst of trading at one price.
 *
 * While sealed the server sends only the trades from before the blackout, so the tape
 * says it has stopped, and why, rather than looking like a slot nobody is trading.
 */
function TradesWindow({ slot, layout }) {
  const status = useMemo(() => slotStatus(slot), [slot])
  const tape = useMemo(() => tapeSummary(slot.all_trades), [slot.all_trades])
  // The server's count, not the tape's length: the tape is only the newest 200.
  const total = Number.isFinite(Number(slot.trade_count)) ? Number(slot.trade_count) : tape.count
  const truncated = total > tape.count
  const failed = status.phase === 'failed'
  const over = truncated ? `Over the latest ${tape.count} trades` : undefined

  const notes = (
    <>
      {status.sealed && (
        <Note tone="amber" glyph="lock">
          Tape frozen at blackout · {dayTime(slot.auction_window_start)}. What fills during
          the auction is published at resolution.
        </Note>
      )}
      {failed && tape.count > 0 && (
        <Note tone="red" glyph="x">
          These trades were reversed when the slot failed to settle; every holder was
          refunded.
        </Note>
      )}
    </>
  )
  const hasNotes = status.sealed || (failed && tape.count > 0)

  if (tape.count === 0) {
    return layout({
      head: hasNotes && notes,
      empty: emptyCopy(status),
    })
  }

  return layout({
    scroll: 'Trades, newest first',
    head: (
      <>
        <StatStrip items={[
          { label: 'Last', value: rate(tape.last) },
          { label: 'VWAP', value: rate(tape.vwap), title: over },
          { label: 'Volume', value: secs(tape.volume), title: over },
          { label: 'Trades', value: String(tape.count) },
        ]} />
        {notes}
      </>
    ),
    body: <Tape tape={tape} />,
    foot: truncated && (
      <p className="tabular-nums text-slate-400">Showing the latest {tape.count} of {total}</p>
    ),
  })
}

export default memo(TradesWindow)

/** The rows, run by run, with the auction runs under their own divider. */
function Tape({ tape }) {
  // Keyed by timestamp, counted within a timestamp: there is no trade id on the wire,
  // and an uncrossing fills several orders in the same instant. An index key would
  // shift every row down one whenever a new trade arrived at the top.
  const seen = new Map()
  const keyOf = t => {
    const n = seen.get(t.timestamp) || 0
    seen.set(t.timestamp, n + 1)
    return `${t.timestamp}#${n}`
  }
  return (
    <div className="space-y-px">
      {tape.groups.map((g, i) => (
        <Fragment key={`${g.kind}-${g.at}-${i}`}>
          {g.kind === 'auction' ? (
            <div className="flex items-center gap-2 pt-1.5 pb-1">
              <span aria-hidden="true" className="h-px w-2 bg-amber-500/40" />
              <span className="text-[9px] uppercase tracking-widest tabular-nums text-amber-300">
                Blind auction fills · {g.rows.length} · {dayTime(g.at)}
              </span>
              <span aria-hidden="true" className="h-px flex-1 bg-amber-500/40" />
            </div>
          ) : i > 0 && (
            // Closes the auction run above, so the continuous trades after it do not
            // read as more of its fills.
            <div aria-hidden="true" className="my-1.5 h-px bg-white/5" />
          )}
          {g.rows.map(t => <TradeRow key={keyOf(t)} t={t} />)}
        </Fragment>
      ))}
    </div>
  )
}

const KIND = {
  auction:   ['Auct', 'text-amber-400'],
  primary:   ['Pri', 'text-violet-400'],
  secondary: ['Sec', 'text-blue-400'],
}

// The time is the column that gives way. In a window three to a dock row (about 220px)
// fixed columns left the price 9px and printed it over its own PRI tag; now the time
// truncates first — whole in its tooltip — and the price keeps room for "$15.4500".
function TradeRow({ t }) {
  const [label, tone] = KIND[t.is_auction_trade ? 'auction' : t.is_primary ? 'primary' : 'secondary']
  const when = new Date(t.timestamp).toLocaleString('en-US', {
    month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' })
  return (
    <div className="relative h-5 grid grid-cols-[minmax(0,5.25rem)_3rem_minmax(3.75rem,1fr)_2rem]
                    items-center gap-2 px-1.5 -mx-1.5 rounded text-[11px] tabular-nums
                    hover:bg-white/[0.03]">
      <span className="text-[10px] text-slate-500 truncate" title={when}>
        {when}
      </span>
      <span className="text-right text-slate-400">{secs(t.quantity)}</span>
      <span className="text-right font-semibold text-white">{rate(t.price)}</span>
      <span className={`text-right text-[9px] font-medium uppercase tracking-wide ${tone}`}>{label}</span>
    </div>
  )
}

