import {
  appendTo, atPath, countLeaves, dedupe, findPath, hasLeaf, isLeaf, prune, replaceAt,
  splitAt, wrapAt,
} from './paneTree.js'
import { GLYPHS, SLOT_WINDOW_KEYS } from './slotWindowMeta.js'

/**
 * The slot page's workspace: which windows sit on its canvas, where a window goes when
 * someone asks for it, and what a reader who has never arranged anything sees.
 *
 * Pure, and free of React and JSX, for the reason `paneTree.js` is: this is the part of
 * the canvas with decisions in it — a default per viewport height, a migration from the
 * layouts people already have, a rule for where a window lands — and decisions are
 * checked against fixtures (slotWorkspace.test.js), not by clicking through them.
 * Storage comes in through a small adapter, `{ get, set, remove, keys }`, so the same
 * code runs on `localStorage` in the page (`browserStorage`) and on a Map in the tests.
 *
 * **Why a new key.** The canvas used to keep its tree under `ag_slot_canvas_tree`, and it
 * saved it on mount. So every visitor who ever opened a slot has `{ key: 'host' }`
 * stored — the slot on its own — and nothing tells the few who chose that from the many
 * who merely loaded the page. Read as a choice, it would keep every one of them away from
 * the windows this layout exists to show; ignored, it would throw away the splits the
 * few did make. So the workspace lives under `ag_slot_workspace_v2`, and the old keys are
 * read on the way in, to carry real arrangements over (`bootWorkspace`). They are never
 * written or deleted from here on, so a rollback finds exactly what everyone had.
 *
 * **Nothing is written until the reader acts.** A layout nobody has touched is not stored
 * at all: it is worked out again on every load from the viewport's tier and the current
 * defaults, so it follows the window as it is resized and picks up whatever the default
 * is tuned to next — exactly what v1 lost by writing down a choice nobody made. The tree
 * is written by the handler that changed it (a chip, a `+`, a close, Reset, the notice's
 * buttons), and wall sizes by `Panes`, after a drag. The one write at boot copies a
 * migrated layout's wall sizes to their new keys, so its walls stay where the reader put
 * them; it never overwrites, so it comes out the same on every load.
 */

// ── Keys ──────────────────────────────────────────────────────────────────────────

/** The reader's workspace tree, or `DEFAULT_MARKER` once they ask for the standard one. */
export const V2_KEY = 'ag_slot_workspace_v2'

/**
 * Written in the tree's place by Reset and "Use the standard layout", already as JSON.
 * Not a tree, so it draws the tier default like an untouched layout does; but it is
 * there, which says the reader has seen the workspace and wants the standard one — no
 * migration and no notice, ever again.
 */
export const DEFAULT_MARKER = JSON.stringify('default')

/** `PaneCanvas`'s storage prefix: wall shares live under `ag_slot_ws:<path>`. */
export const SIZES_PREFIX = 'ag_slot_ws'

/** `"done"` once the one-time notice for returning visitors has been answered. */
export const NOTICE_KEY = 'ag_slot_ws_notice'

// v1, read-only from here on: the tree, its wall sizes (`ag_slot_canvas:<path>`), and
// the seed the tree itself started from.
export const V1_KEY = 'ag_slot_canvas_tree'
export const V1_SIZES = 'ag_slot_canvas'
export const LEGACY_KEY = 'ag_split_slot_channel_on'

// ── Viewport ──────────────────────────────────────────────────────────────────────

/**
 * Room for a canvas: `md` wide, as before, and now 560px tall as well. Under that, a
 * canvas of windows each a few lines high is worse than a page that scrolls, so a
 * landscape phone, a short desktop window or 150% zoom on a laptop gets flow mode.
 */
export const CANVAS_QUERY = '(min-width: 768px) and (min-height: 560px)'

/** Short: the rail drops to two windows, so each keeps a body worth scrolling. */
export const SHORT_QUERY = '(max-height: 679px)'

/** Tall and wide: Trades and Holders dock under the chart, both still 340px wide. */
export const TALL_QUERY = '(min-height: 940px) and (min-width: 1200px)'

/**
 * The tier from the two queries' answers: 'short', 'tall' or 'standard'. They cannot
 * both match — one needs under 680px of height, the other 940px or more.
 */
export const tierFor = ({ short, tall }) => (short ? 'short' : tall ? 'tall' : 'standard')

// ── Storage ───────────────────────────────────────────────────────────────────────

/**
 * `localStorage` behind the adapter. Every call is wrapped: storage throws in a private
 * window and when site data is blocked, and a page that cannot remember its layout must
 * still draw one. A read that fails is a read of nothing.
 */
export const browserStorage = {
  get(key) {
    try { return localStorage.getItem(key) } catch { return null }
  },
  set(key, value) {
    try { localStorage.setItem(key, value) } catch { /* private window */ }
  },
  remove(key) {
    try { localStorage.removeItem(key) } catch { /* ditto */ }
  },
  // A copy, so a caller can remove keys while it walks them.
  keys() {
    try {
      const out = []
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i)
        if (k !== null) out.push(k)
      }
      return out
    } catch { return [] }
  },
}

/** Stored JSON, or null when there is none or it does not parse. */
function parse(raw) {
  if (raw == null) return null
  try { return JSON.parse(raw) } catch { return null }
}

// ── Windows ───────────────────────────────────────────────────────────────────────

/**
 * The windows that can sit beside a slot and are whole pages.
 *
 * Routes, not components: each pane is the real page in an iframe on the same origin
 * (see `RoutePane`), so what belongs here is anything a slot is read alongside. The
 * canvas never invents one of these — what may go in a pane is app knowledge.
 *
 * `to` is given the slot so a window can be about *this* slot rather than the
 * product in

def slot_list(request):
    creator_id  = request.query_params.get('creator_id')
    include_all = request.query_params.get('include_all')

    qs = Slot.objects.select_related('creator')
    # When browsing the market show only tradeable slots; when viewing a specific
    # creator's own listings pass include_all=1 to see every phase.
    if not (creator_id and include_all):
        qs = qs.filter(phase__in=OPEN_PHASES)

    slot_type = request.query_params.get('slot_type')
    if slot_type:
        qs = qs.filter(slot_type=slot_type)
    platform = request.query_params.get('platform')
    if platform:
        qs = qs.filter(creator__platform=platform)
    if creator_id:
        qs = qs.filter(creator_id=creator_id)

    user = request.user if request.user.is_authenticated else None
    return Response([_slot_to_dict(s, user=user) for s in qs.order_by('-issued_at')[:50]])


@api_view(['GET'])
def slot_detail(request, slot_id):
    try:
        slot = Slot.objects.select_related('creator').prefetch_related('positions__user', 'trades').get(id=slot_id)
    except Slot.DoesNotExist:
        return Response({'error': 'Slot not found.'}, status=404)
    user = request.user if request.user.is_authenticated else None
    return Response(_slot_to_dict(slot, user=user))


# ---------------------------------------------------------------------------
# Slots — Creator issues a slot
# ---------------------------------------------------------------------------

