def creator_metrics(request, creator_id):
    """
    A channel's figures over time, for the charts on its public page.

    Defaults to everything since the channel registered. ?range= narrows it to
    1h / 24h / 7d / 30d / 90d / 1y, or 'all'.

    Served through services.channel_series, the same builder the developer dashboard
    uses, so the two cannot disagree about a channel's history.
    """
    from .services import channel_series

    try:
        creator = CreatorProfile.objects.get(id=creator_id, delisted=False)
    except CreatorProfile.DoesNotExist:
        return Response({'error': 'Creator not found.'}, status=404)

    # §4.8's opt-out "covers consolidation outcomes only", and channel metrics are not
    # one — they are the channel's own figures, published on its public page either way.
    # This used to close the whole series, which took more than the opt-out grants.

    range_key = request.query_params.get('range', channel_series.DEFAULT_RANGE)
    if range_key not in channel_series.RANGES:
        return Response({'error': f'range must be one of '
                                  f'{", ".join(channel_series.RANGES)}.'}, status=400)

    slot_type = request.query_params.get('slot_type', 'active_integration')
    if slot_type not in VALID_SLOT_TYPES:
        return Response({'error': f'slot_type must be one of '
                                  f'{", ".join(VALID_SLOT_TYPES)}.'}, status=400)

    data = channel_series.series(creator, range_key, slot_type=slot_type)
    return Response({
        'creator_id':      creator.id,
        'handle':          creator.handle,
        'history_visible': True,
        'range':           range_key,
        'ranges':          list(channel_series.RANGES),
        'is_mock':         creator.use_mock_metrics or creator.is_mock,
        'server_now':      get_now().isoformat(),
        **data,
    })


