import { useMemo, useState } from 'react'
import { Link, Navigate, useNavigate, useParams } from 'react-router-dom'
import Navbar from '../components/Navbar'
import LiveDot from '../components/LiveDot'
import PhaseChip from '../components/slot/PhaseChip'
import SlotWindow from '../components/slot/SlotWindow'
import useSlot from '../hooks/useSlot'
import { useAuth } from '../context/AuthContext'
import { IS_PANE } from '../utils/pane'
import { SLOT_WINDOW_KEYS } from '../utils/slotWindowMeta'

/**
 * One slot window as a page of its own: `/slot/:id/panel/:key`.
 *
 * Where a window's Open ↗ goes. The workspace is one screen, and the best canvas there
 * is is a second one — so any of the six windows can leave the slot page for a tab or
 * a monitor of its own, and keep updating there.
 *
 * It is the same window, not a page made to look like it: SlotWindow draws it from
 * the same `useSlot` feed at the same 6s cadence, with the same title bar, figures and
 * sealed states, so the two copies of a window can never disagree by more than a poll.
 * What it has no use for is the workspace around it. The frame carries no ×, no `+`
 * and no Open ↗ — there is nothing to close it into, nothing to put beside it, and it
 * is already the page — and whatever belongs to the workspace leads back there: the
 * header's "← Slot #id", and the two actions that need the Participate tab (placing a
 * sealed order, declaring the consolidation date), which land on it through
 * `#participate`.
 *
 * Earliest/Latest are this page's own state. On the slot page they are shared with
 * the chart's milestones; here there is no chart to share them with.
 */
export default function SlotPanelPage() {
  const { id, key } = useParams()
  // Checked before anything loads: a key that names no window has nothing to show,
  // and the slot it was meant for is the useful place to land.
  if (!SLOT_WINDOW_KEYS.includes(key)) return <Navigate to={`/slot/${id}`} replace />
  return <SlotPanel id={id} windowKey={key} />
}

function SlotPanel({ id, windowKey }) {
  const navigate = useNavigate()
  const { user, creatorProfile } = useAuth()
  const { slot, loading, notFound, stale, revision, clock } = useSlot(id)
  const [showEarliest, setShowEarliest] = useState(true)
  const [showLatest,   setShowLatest]   = useState(true)

