import { cloneElement } from 'react'
import Panes from './Panes'
import { countLeaves, isLeaf, leavesOf } from '../utils/paneTree'

/**
 * Several windows arranged in both axes at once.
 *
 * `Panes` splits along one direction: a row of panes, or a column of them. That is
 * enough for a page beside its companion and not enough for a board — the moment you
 * want the channel beside the slot *and* the order book under the channel, one
 * direction cannot express it.
 *
 * A canvas is a tree — see `utils/paneTree.js`, which holds the shape and every
 * operation on it, deliberately free of React so the only part of this with real
 * logic in it can be reasoned about without a renderer.
 *
 * Rendering it is the recursion `Panes` already supports: a split becomes a `Panes`
 * with that direction, and a split child of a `Panes` nests rather than scrolling.
 * The children are built by a plain recursive **function** rather than a component,
 * because `Panes` recognises a nested split by element type and a wrapper component
 * in between would hide it. All the dragging, the per-layout sizes and the
 * localStorage persistence come from `Panes` unchanged; what is added here is the
 * tree, the operations on it, and remembering its shape.
 *
 * **Each split gets its own storage key, derived from its path in the tree.** Sizes
 * belong to a boundary, not to the canvas, so moving one wall must not disturb
 * another. The cost is that restructuring the tree reassigns paths and a split can
 * inherit the sizes of the one that used to live at its path — acceptable, because
 * the alternative is a size that follows a node around and has to be garbage
 * collected when it goes.
 *
 * **A split's `weights` are handed to its `Panes` as the hint** it draws until the
 * reader drags a wall, and returns to on a double-click or Home. That is how a host
 * designs a layout — the chart at 64% beside a rail — without writing a size for
 * anyone who has not moved one.
 *
 * **`rev` is part of every React key and of no storage key.** Bumping it remounts
 * every split and window, so each `Panes` reads its storage and its hint afresh — what
 * a layout reset needs once the host has cleared the stored sizes — while the sizes
 * stay filed under the same paths as before.
 *
 * **`labelOf(node)` names the panes for the walls between them**, so a wall reads
 * "Resize Trade price and Listing" rather than "Resize pane 1". A split the host has
 * no name for goes by its first window, the one that heads it.
 *
 * **The host renders the leaves and owns what a window is.** `render(leaf, controls)`
 * gets `split(dir, leaf)`, `close()` and the leaf's `path`; it decides what may go in
 * a new pane, because that is app knowledge and not layout knowledge. The canvas
 * never invents a leaf.
 *
 * **Splitting in the direction a pane's parent already runs adds a sibling**, rather
 * than nesting a second split inside it. Three panes in a row is what someone asking
 * for a third column means, and nesting would give them a row containing a row —
 * same picture, two walls that behave differently, and a tree that deepens every
 * time anyone touches it.
 */

export default function PaneCanvas({
  tree, render, storageKey = 'ag_canvas', className = '',
  split, close, collapseTo = 0, rev = 0, labelOf,
}) {
  const leaves = countLeaves(tree)

  // A split the host has no name for goes by the window that heads it.
  const nameOf = c => {
    const own = labelOf(c)
    if (own || isLeaf(c)) return own
    const head = leavesOf(c)[0]
    return head ? labelOf(head) : undefined
  }

  // A plain function, not a component: `Panes` spots a nested split by element type,
  // and a wrapper in between would make every child look like a document.
  const node = (n, path) => {
    const id = path.join('.') || 'root'
    const key = `${rev}:${id}`
    if (isLeaf(n)) {
      const el = render(n, {
        path,
        split: (dir, leaf) => split?.(path, dir, leaf),
        close: () => close?.(path),
        // The last window cannot be closed — there would be nothing to show.
        canClose: leaves > 1,
      })
      // Keyed here rather than left to the host: the key belongs to this child's
      // position in the split, which is the canvas's business and not the leaf's,
      // and a host that forgot it would get React remounting panes on every
      // restructure. cloneElement keeps the element's type, so a host that returns
      // a nested `Panes` of its own is still recognised as a split.
      return el ? cloneElement(el, { key }) : null
    }
    const kids = n.children || []
    return (
      <Panes
        key={key}
        storageKey={`${storageKey}:${id}`}
        direction={n.dir}
        initial={n.weights}
        labels={labelOf ? kids.map(nameOf) : undefined}
        // No bottom edges. The canvas is one viewport tall and its walls size every
        // window, so a pane pulled shorter only left dead board, and the height it
        // stored stayed with its position: a window added under it later turned that
        // position into a split pinned at the old height, with no handle to undo it.
        // Turning them off also ignores any height an earlier version stored.
        edges={false}
        // Below `md` everything stacks into one column, and a tree of windows on a
        // phone is worse than the first one of them. The host names which that is.
        collapseTo={path.length === 0 ? collapseTo : null}
        className="flex-1"
      >
        {kids.map((c, i) => node(c, [...path, i]))}
      </Panes>
    )
  }

  return (
    <div className={`min-h-0 min-w-0 flex flex-col ${className}`}>
      {node(tree, [])}
    </div>
  )
}

