import unicodedata, sys

def dw(s):
    w = 0
    for ch in s:
        if unicodedata.combining(ch):
            continue
        w += 2 if unicodedata.east_asian_width(ch) in ('W', 'F') else 1
    return w

def pad(s, n):
    d = dw(s)
    if d > n:
        # truncate by display width, keep an ellipsis
        out, w = '', 0
        for ch in s:
            cw = 2 if unicodedata.east_asian_width(ch) in ('W', 'F') else 1
            if w + cw > n - 1:
                break
            out += ch; w += cw
        return out + '…' + ' ' * (n - w - 1)
    return s + ' ' * (n - d)

def box(title, right, lines, width, foot=None):
    """A window: ┌ title ─── right ┐, body lines, optional ├ foot ┤, └───┘. width = outer width."""
    inner = width - 2
    t = f' {title} '
    r = f' {right} ' if right else ''
    fill = inner - dw(t) - dw(r)
    if fill < 1:
        r = ''
        fill = inner - dw(t)
    out = ['┌' + t + '─' * fill + r + '┐']
    for l in lines:
        if l == '---':
            out.append('├' + '─' * inner + '┤')
        else:
            out.append('│' + pad(l, inner) + '│')
    if foot:
        out.append('├' + '─' * inner + '┤')
        for f in foot:
            out.append('│' + pad(f, inner) + '│')
    out.append('└' + '─' * inner + '┘')
    return out

def side(a, b, gap=1):
    """Two columns of lines side by side; b may be a list of boxes stacked."""
    wa = max(dw(x) for x in a) if a else 0
    wb = max(dw(x) for x in b) if b else 0
    n = max(len(a), len(b))
    res = []
    for i in range(n):
        la = a[i] if i < len(a) else ''
        lb = b[i] if i < len(b) else ''
        res.append(pad(la, wa) + ' ' * gap + pad(lb, wb))
    return res

def frame(lines, width, label=None):
    """Outer screen frame."""
    inner = width - 2
    out = ['┌' + '─' * inner + '┐']
    for l in lines:
        out.append('│' + pad(l, inner) + '│')
    out.append('└' + '─' * inner + '┘')
    return out

def row(cols):
    """cols: list of (text, width)"""
    return ''.join(pad(t, w) for t, w in cols)
